// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

// Minimal copies of Neuron's needed surface + contract, since C requires it.
// We re-implement a tiny NRN token matching Neuron's interface used by C.
contract TinyNRN {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    function mint(address to, uint256 amount) external { balanceOf[to] += amount; }
    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "bal");
        require(allowance[from][msg.sender] >= amount, "allow");
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;
        return true;
    }
    function approveSpender(address account, uint256 amount) external {
        allowance[account][msg.sender] = amount;
    }
}

contract InvMutTest is Test {
    GameItems c;
    TinyNRN nrn;

    function setUp() public {
        c = new GameItems(address(this), address(this));
        nrn = new TinyNRN();
        c.instantiateNeuronContract(address(nrn));
        c.createGameItem("item", "uri", false, true, 0, 1, type(uint16).max);
    }

    function testFuzz_property(address actor, uint256 quantity) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        quantity = bound(quantity, 1, type(uint16).max);

        // give the buyer funds and let it purchase `quantity` units of item 0 (price 1 each)
        nrn.mint(actor, quantity);
        vm.prank(actor);
        c.mint(0, quantity);

        // The buyer's balance for token 0 must reflect the purchase of the queried account.
        assertTrue(c.balanceOf(actor, 0) == quantity);
    }
}
